"""Finds the ends of URLs (Strips following punctuation)"""
def tinyurlFindUrlend(msg: Any, urlstart: Any) -> object {
    m = msg[urlstart:];
    index = m.find(" ");
    if (index == -1) {
        index = len(m);
    }
    while (msg[(index - 1)] in ("?", ".", "!")) {
        index -= 1;
    }
    return (index + urlstart);
}

